def add(kind,name,**rest):
 o={'apiVersion':'apps/v1' if kind in ['Deployment','StatefulSet'] else 'networking.k8s.io/v1' if kind=='NetworkPolicy' else 'v1','kind':kind,'metadata':{'name':name,'namespace':ns},**rest};items.append(o);return o
def svc(name,ports,headless=False):
 add('Service',name,spec={'selector':{'app':name},'ports':[{'name':f'p{p}','port':p,'targetPort':p} for p in ports],**({'clusterIP':'None','publishNotReadyAddresses':True} if headless else {})})
def pvc(name,size):add('PersistentVolumeClaim',name,spec={'accessModes':['ReadWriteOnce'],'resources':{'requests':{'storage':size}}})
def workload(name,image,ports,env=None,command=None,mount=None,memory='512Mi',cpu='250m',limit='1Gi',replicas=1,probe=None,kind='Deployment',volumes=None):
 c={'name':name,'image':image,'imagePullPolicy':'IfNotPresent','ports':[{'containerPort':p} for p in ports],'resources':{'requests':{'cpu':cpu,'memory':memory},'limits':{'memory':limit}}}
 if env:c['env']=[{'name':k,'value':str(v)} for k,v in env.items()]
 if command:c['command']=command
 if mount:c['volumeMounts']=mount
 if probe:c.update({'readinessProbe':{'httpGet':{'path':probe,'port':ports[0]},'periodSeconds':5,'timeoutSeconds':3},'startupProbe':{'httpGet':{'path':probe,'port':ports[0]},'periodSeconds':5,'failureThreshold':90,'timeoutSeconds':3}})
 pod={'containers':[c],'terminationGracePeriodSeconds':45}
 if volumes:pod['volumes']=volumes
 spec={'replicas':replicas,'selector':{'matchLabels':{'app':name}},'template':{'metadata':{'labels':{'app':name}},'spec':pod}}
 if kind=='StatefulSet':spec['serviceName']=name
 else:spec['strategy']={'type':'Recreate'} if mount else {'type':'RollingUpdate','rollingUpdate':{'maxUnavailable':0,'maxSurge':1}}
 add(kind,name,spec=spec);svc(name,ports,kind=='StatefulSet');return c,pod,spec
