redis_script='set -eu\nmaster=""\nfor i in 0 1 2; do\n master=$(redis-cli -h sentinel-$i.sentinel -p 26379 -a "$SENTINEL_PASSWORD" --no-auth-warning --raw SENTINEL get-master-addr-by-name s2t-stress-master 2>/dev/null | head -n 1) || true\n [ -n "$master" ] && break\ndone\nif [ -z "$master" ]; then master=redis-0.redis.s2t-stress-20261005.svc.cluster.local; fi\nown="$HOSTNAME.redis.s2t-stress-20261005.svc.cluster.local"\nif [ "$master" = "$own" ]; then\n exec redis-server --requirepass "$REDIS_PASSWORD" --masterauth "$REDIS_PASSWORD" --appendonly yes --dir /data --replica-announce-ip "$own" --replica-announce-port 6379\nelse\n exec redis-server --requirepass "$REDIS_PASSWORD" --masterauth "$REDIS_PASSWORD" --appendonly yes --dir /data --replicaof "$master" 6379 --replica-announce-ip "$own" --replica-announce-port 6379\nfi'
c,p,s=workload('redis','redis:7.4-alpine',[6379],env={'REDIS_PASSWORD':credentials['redis'],'SENTINEL_PASSWORD':credentials['sentinel']},command=['sh','-c',redis_script],mount=mount('/data'),memory='64Mi',cpu='100m',limit='256Mi',replicas=3,kind='StatefulSet');s['podManagementPolicy']='Parallel';s['volumeClaimTemplates']=[{'metadata':{'name':'data'},'spec':{'accessModes':['ReadWriteOnce'],'resources':{'requests':{'storage':'512Mi'}}}}];c['readinessProbe']={'exec':{'command':['sh','-c','redis-cli -a "$REDIS_PASSWORD" --no-auth-warning ping | grep PONG']},'periodSeconds':3};c['livenessProbe']=c['readinessProbe']
sentinel_script='set -eu\nif [ ! -f /data/sentinel.conf ]; then\ncat > /data/sentinel.conf <<CFG\nport 26379\nbind 0.0.0.0\nprotected-mode yes\nrequirepass $SENTINEL_PASSWORD\nsentinel resolve-hostnames yes\nsentinel announce-hostnames yes\nsentinel announce-ip $HOSTNAME.sentinel.s2t-stress-20261005.svc.cluster.local\nsentinel monitor s2t-stress-master redis-0.redis.s2t-stress-20261005.svc.cluster.local 6379 2\nsentinel auth-pass s2t-stress-master $REDIS_PASSWORD\nsentinel sentinel-pass $SENTINEL_PASSWORD\nsentinel down-after-milliseconds s2t-stress-master 2000\nsentinel failover-timeout s2t-stress-master 15000\nsentinel parallel-syncs s2t-stress-master 1\nCFG\nfi\nsed -i \'/^sentinel announce-ip /d; /^sentinel announce-hostnames /d; /^sentinel resolve-hostnames /d\' /data/sentinel.conf\nprintf \'sentinel resolve-hostnames yes\\nsentinel announce-hostnames yes\\nsentinel announce-ip %s\\n\' "$HOSTNAME.sentinel.s2t-stress-20261005.svc.cluster.local" >> /data/sentinel.conf\nexec redis-server /data/sentinel.conf --sentinel'
